Method.Implementation:
	#dim tSC As %Status=$$$OK
    set tSC=..Adapter.SetAutoCommit(1) 

	$$$TRACE("Inside "_..%ConfigName_" Method CategoryLookup")

	set pResponse=##class(IHC.ITF.Response.DwDbInsQueryResponse).%New()
	set pResponse.NAME =  ""     
    set pResponse.CATEGORYNAME1 =  ""  
    set pResponse.CATEGORYNAME2 = ""
	if (pRequest.FSCNUMBER > 0){

	    try{	
 	      set tSC=..Adapter.ExecuteQuery(.tResult,"SELECT NAME, REPORTING_CATEGORY__1, REPORTING_CATEGORY__2, D2.CATEGORY_NAME As CatName1, D3.CATEGORY_NAME As CatName2, D1.INACTIVE_FLAG FROM DBO.DN19 D1 JOIN DBO.DN77 D2 ON D1.REPORTING_CATEGORY__1 = D2.RECORD_NUMBER JOIN DBO.DN77 D3 ON D1.REPORTING_CATEGORY__2 = D3.RECORD_NUMBER WHERE FSC_NUMBER = "_
 	      pRequest.FSCNUMBER _ " AND D1.Inactive_flag = 'N'")
 	      $$$TRACE("  SUCCESS : "_tSC)		 	   	
	    }CATCH err {		
	      $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	      set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	    }	
	    $$$TRACE(" ExecuteQuery STATUS: "_tSC _ "tResult: "_tResult)
	    If tResult.Next() {
          set pResponse.NAME =  tResult.GetData(1)   
          set pResponse.CATEGORY1 =  tResult.GetData(2)
          set pResponse.CATEGORY2 =  tResult.GetData(3) 
          set pResponse.CATEGORYNAME1 =  tResult.GetData(4) 
          set pResponse.CATEGORYNAME2 =  tResult.GetData(5)
          set pResponse.INACTIVE =  tResult.GetData(6)
        }   

	}
	else {
	   set tSC = $$$ERROR( "FSCNUMBER is not valid: " _ pRequest.FSCNUMBER)	    
	}

	$$$TRACE(" DW RESPONSE : "_ pResponse.NAME)	
	quit tSC
